export type ValidationResult = { valid: boolean; error?: string };

export type Validator = (value: string) => ValidationResult;
export type AsyncValidator = (value: string) => Promise<ValidationResult>;

/** Validates that a field is not empty. */
export function required(message = 'This field is required'): Validator {
  return (_value) => ({ valid: false, error: message }); // TODO
}

/** Validates email format. */
export function email(message = 'Invalid email address'): Validator {
  return (_value) => ({ valid: false, error: message }); // TODO
}

/** Validates that value is a number. */
export function isNumber(message = 'Must be a number'): Validator {
  return (_value) => ({ valid: false, error: message }); // TODO
}

/** Validates minimum string length. */
export function minLength(min: number, message?: string): Validator {
  return (_value) => ({ valid: false, error: message ?? `Min length is ${min}` }); // TODO
}

/**
 * Run multiple validators and return first failure.
 * If all pass, return { valid: true }.
 */
export function validate(value: string, validators: Validator[]): ValidationResult {
  return { valid: false }; // TODO
}

/**
 * Run validators including async ones sequentially.
 * Returns first failure or { valid: true }.
 */
export async function validateAsync(
  value: string,
  validators: (Validator | AsyncValidator)[]
): Promise<ValidationResult> {
  return { valid: false }; // TODO
}

