import { required, email, isNumber, minLength, validate, validateAsync } from './validator';

test('required passes for non-empty', () => {
  expect(validate('hello', [required()])).toEqual({ valid: true });
});

test('required fails for empty', () => {
  const r = validate('', [required()]);
  expect(r.valid).toBe(false);
  expect(r.error).toBeTruthy();
});

test('email passes for valid email', () => {
  expect(validate('test@example.com', [email()])).toEqual({ valid: true });
});

test('email fails for invalid', () => {
  expect(validate('notanemail', [email()]).valid).toBe(false);
  expect(validate('@no-local.com', [email()]).valid).toBe(false);
});

test('isNumber passes for number string', () => {
  expect(validate('42', [isNumber()])).toEqual({ valid: true });
  expect(validate('3.14', [isNumber()])).toEqual({ valid: true });
});

test('isNumber fails for non-number', () => {
  expect(validate('hello', [isNumber()]).valid).toBe(false);
});

test('minLength passes when long enough', () => {
  expect(validate('abcde', [minLength(3)])).toEqual({ valid: true });
});

test('minLength fails when too short', () => {
  expect(validate('ab', [minLength(3)]).valid).toBe(false);
});

test('validate returns first error', () => {
  const r = validate('', [required(), email()]);
  expect(r.valid).toBe(false);
  // Should fail on required first
});

test('validateAsync with sync validators', async () => {
  const r = await validateAsync('hello', [required(), minLength(3)]);
  expect(r).toEqual({ valid: true });
});

test('validateAsync with async validator', async () => {
  const asyncCheck: import('./validator').AsyncValidator = async (v) =>
    v === 'taken' ? { valid: false, error: 'Username taken' } : { valid: true };
  const r = await validateAsync('taken', [required(), asyncCheck]);
  expect(r.valid).toBe(false);
  expect(r.error).toBe('Username taken');
});
